DO $chem_batch$
DECLARE
  sql text;
  stmt text;
BEGIN
  sql := convert_from(decode('', 'base64'), 'utf8');
  FOREACH stmt IN ARRAY regexp_split_to_array(rtrim(sql, E'; \n\r'), E';\r?\n')
  LOOP
    stmt := btrim(stmt);
    IF stmt <> '' THEN
      EXECUTE stmt;
    END IF;
  END LOOP;
END
$chem_batch$;
